        // ... (중략: 추출 로직)

        // finally 블록 내 수정
        } finally {
          processedCount++;

          // [추가] ETA 계산
          const now = Date.now();
          const elapsedSeconds = (now - startTime) / 1000;
          if (processedCount > 0) {
             const avgTimePerSegment = elapsedSeconds / processedCount;
             const remainingSegments = totalSegments - processedCount;
             const eta = Math.ceil(avgTimePerSegment * remainingSegments);

