### 수정된 코드 (`src/pages/ReviewPage.tsx`)

```tsx
// pages/ReviewPage.tsx
// 검토 및 수정 페이지

import React, { useState, useMemo, useCallback, useEffect } from 'react';
import { 
  CheckCircle, AlertTriangle, RefreshCw, Copy, Eye, EyeOff, 
