            원문 {result.originalText.length}자 → 번역 {result.translatedText.length}자 ({ratio}%)
          </span>
        </div>

        {/* 우측 아이콘 버튼들 (기존과 동일) */}
        <div className="flex items-center gap-1">
          {result.success && !isEditing && (
            <IconButton 
              type="button"
              onClick={handleDiscardClick} 
